// === Tab: mySketch ===
const tileX = 14;
const tileY = 11;
let TS, cci, grid;
const clrs = ["white", "white", "blue", "red", "red"];

function setup() {
	let TSX = windowWidth / tileX;
	let TSY = windowHeight / tileY;
	TS = floor(min(TSX, TSY));
	createCanvas(TS * tileX, TS * tileY);
	pixelDensity(1);
	frameRate(5)
	loop();

	// erase grid
	grid = [];
	for (let y = 0; y < tileY; y++) {
		grid[y] = [];
		for (let x = 0; x < tileX; x++) grid[y][x] = 0;
	}
	// current color index
	cci = 1; // 0 is transparent
}

function draw() {
	background("azure");

	stroke(128, 128);
	noFill();
	for (let y = 0; y < tileY; y++) {
		for (let x = 0; x < tileX; x++) {
			const n = noise((x + frameCount) * 0.0512, (y + 1) * 0.0521); // , frameCount * 0.05832);
			const i = floor(clrs.length * n);
			fill(clrs[i])
			// fill(random(clrs))
			if (grid[y][x]) fill(clrs[grid[y][x] - 1])

			rect(x * TS, y * TS, TS, TS);
		}
	}

}

function mousePressed() {
	if (mouseButton === LEFT) {
		const x = floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width * tileX);
		const y = floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height * tileY);
		if (x >= 0 && y >= 0 && x < tileX && y < tileY) {
			grid[y][x] = cci;
		}
	}
}

function keyPressed() {
	const numCode = key.charCodeAt(0) - 48;
	// console.log(numCode)
	if (numCode >= 0 && numCode <= clrs.length ) {
		cci = numCode; // index of clrs, 0 = erase
	}
}
